import java.io.*;import java.util.*;import com.jpexs.decompiler.flash.SWF;import com.jpexs.decompiler.flash.tags.DefineSpriteTag;import com.jpexs.decompiler.flash.tags.base.ImageTag;
class ProbeNext2{public static void main(String[]a)throws Exception{try(var in=new FileInputStream(a[0])){var s=new SWF(in,true);for(int id:new int[]{1163,1185,1027,1080,3758}){var t=s.getCharacter(id);if(!(t instanceof DefineSpriteTag d)){System.out.println(id+" NOT SPRITE "+t);continue;}Set<Integer>ids=new TreeSet<>();Set<String>imports=new TreeSet<>();d.getNeededCharactersDeep(ids,imports);System.out.print("SPRITE "+id+" frames="+d.frameCount+" dependencies="+ids.size()+" bitmaps=");for(int x:ids)if(s.getCharacter(x) instanceof ImageTag im){var z=im.getImageDimension();System.out.print(x+":"+z.width+"x"+z.height+" ");}System.out.println();}}}}
